import{_ as t,H as n,f as a,i as l}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"结束语 | 如何设计一个具体领域的Agent？","description":"","frontmatter":{},"headers":[{"level":2,"title":"先定整体架构：优先考虑多 Agent 协作","slug":"先定整体架构-优先考虑多-agent-协作","link":"#先定整体架构-优先考虑多-agent-协作","children":[]},{"level":2,"title":"第一站：先听懂用户到底在说什么","slug":"第一站-先听懂用户到底在说什么","link":"#第一站-先听懂用户到底在说什么","children":[]},{"level":2,"title":"第二站：意图识别不能只是调用一次大模型","slug":"第二站-意图识别不能只是调用一次大模型","link":"#第二站-意图识别不能只是调用一次大模型","children":[]},{"level":2,"title":"第三站：复杂任务使用 Plan + ReAct","slug":"第三站-复杂任务使用-plan-react","link":"#第三站-复杂任务使用-plan-react","children":[]},{"level":2,"title":"第四站：有 Plan，就一定要提 Replan","slug":"第四站-有-plan-就一定要提-replan","link":"#第四站-有-plan-就一定要提-replan","children":[]},{"level":2,"title":"第五站：一定要提上下文管理","slug":"第五站-一定要提上下文管理","link":"#第五站-一定要提上下文管理","children":[{"level":3,"title":"C 端 Agent，尽量主动提用户画像","slug":"c-端-agent-尽量主动提用户画像","link":"#c-端-agent-尽量主动提用户画像","children":[]}]},{"level":2,"title":"第六站：检索要同时讲“有什么数据”和“怎么查”","slug":"第六站-检索要同时讲-有什么数据-和-怎么查","link":"#第六站-检索要同时讲-有什么数据-和-怎么查","children":[]},{"level":2,"title":"最后一句带过可观测性","slug":"最后一句带过可观测性","link":"#最后一句带过可观测性","children":[]},{"level":2,"title":"最终通用话术模板","slug":"最终通用话术模板","link":"#最终通用话术模板","children":[]},{"level":2,"title":"最后：不要只准备答案，要准备证据","slug":"最后-不要只准备答案-要准备证据","link":"#最后-不要只准备答案-要准备证据","children":[]}],"relativePath":"AIAgent系统设计面试现场/结束语｜如何设计一个具体领域的Agent？.md","filePath":"AIAgent系统设计面试现场/结束语｜如何设计一个具体领域的Agent？.md","lastUpdated":1795451227000}'),i={name:"AIAgent系统设计面试现场/结束语｜如何设计一个具体领域的Agent？.md"};function p(r,e,o,A,g,h){return n(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="结束语-如何设计一个具体领域的agent" tabindex="-1">结束语 | 如何设计一个具体领域的Agent？ <a class="header-anchor" href="#结束语-如何设计一个具体领域的agent" aria-label="Permalink to &quot;结束语 | 如何设计一个具体领域的Agent？&quot;">​</a></h1><p>你好，我是大明。</p><p>到这里，专栏最核心的内容已经全部讨论完毕。终于来到最后一讲，我还想再多叮嘱几句—— 学习这个专栏的小伙伴，有些是刚毕业的学生，还有很大一部分是希望转型 Agent 的初、中级软件工程师。所以在结束语里，我想继续强调一个问题：如果让你设计一个具体领域的 Agent，你会怎么做？具体的面试“骨架”是怎样的？这道题让不少小伙伴折戟沉沙，非常值得在课程最后再串一遍。</p><p>前面二十多讲已经把相关知识详细展开过，这一讲我们要做的是把它们串联起来，整理出一套通用的回答框架，确保你能从容应对。就像开考前老师划重点一样。先明确一点：不同级别、不同目标薪资，回答的复杂度必然不同。</p><p>如果你是初级工程师，能把“大模型 + Tool + RAG”讲清楚，基本就够用了。但如果面试的是高级工程师及以上岗位，就必须体现出 Agent 的工程复杂度。下面这套回答框架偏向高级工程师及以上版本，你可以根据自己的项目经历做相应删减。</p><h2 id="先定整体架构-优先考虑多-agent-协作" tabindex="-1">先定整体架构：优先考虑多 Agent 协作 <a class="header-anchor" href="#先定整体架构-优先考虑多-agent-协作" aria-label="Permalink to &quot;先定整体架构：优先考虑多 Agent 协作&quot;">​</a></h2><p>如果面试官没有明确表达不喜欢多 Agent，也不是一个明显简单到一句 Prompt 就能搞定的场景，那么你可以优先设计主 Agent + 多个领域子 Agent 架构模式。</p><p>主 Agent 负责用户理解、任务规划、上下文管理和任务调度；子 Agent 根据业务拆分，例如检索 Agent、推荐 Agent、售后 Agent、执行 Agent 等。</p><p>我可以明确说，在实践中我不太推荐什么多 Agent 协作架构，但是面试就是喜欢多 Agent 架构。正如同在互联网里面，我也不建议搞微服务，但是架不住面试官就喜欢微服务。而且你可能还要给出一个为什么用多 Agent 架构的解释：不同业务域需要的 Spec、Context 和 Tool 差异比较大，所以通过子 Agent 做隔离。</p><p>说清楚这一点就够了，不要继续展开架构细节。</p><h2 id="第一站-先听懂用户到底在说什么" tabindex="-1">第一站：先听懂用户到底在说什么 <a class="header-anchor" href="#第一站-先听懂用户到底在说什么" aria-label="Permalink to &quot;第一站：先听懂用户到底在说什么&quot;">​</a></h2><p>接着你介绍在 Agent 里面收到用户输入之后，不要马上开始执行，要先处理用户输入规范化，包括：</p><ul><li><p>“这个”“那个”“第一个”的指代消解；</p></li><li><p>省略信息补全；</p></li><li><p>口语、病句、黑话、缩写；</p></li><li><p>“更划算”“更高级”“最近”这种需要进一步解释的表达。</p></li></ul><p>这里最适合埋一个面试钩子，比如说“我们还专门处理过跨多轮指代，以及性价比这种需要结合上下文、用户画像甚至工具结果才能量化的表达。”说到这里停下来。面试官如果追问，你再展开前面的内容。</p><h2 id="第二站-意图识别不能只是调用一次大模型" tabindex="-1">第二站：意图识别不能只是调用一次大模型 <a class="header-anchor" href="#第二站-意图识别不能只是调用一次大模型" aria-label="Permalink to &quot;第二站：意图识别不能只是调用一次大模型&quot;">​</a></h2><p>用户输入理解之后，你要说 Agent 需要考虑做意图识别，当然你也可以说做目标识别。也就是理解用户的目标。重点不在于介绍你用了什么模型，而是告诉面试官意图识别决定后续加载什么 Spec、组织什么 Context、开放什么 Tool，以及进入什么业务流程。</p><p>输出也不要只有一个 Intent，要说是一个结构化的输出，至少包括意图以及意图所需的参数。缺参数就澄清，系统不支持就拒识，不要什么输入都强行往某个意图里面塞。</p><p>如果你想刷一个亮点，可以提一句意图特别多的时候，不要全部塞给大模型，而是先召回候选意图，再做最终识别。然后等面试官追问。</p><h2 id="第三站-复杂任务使用-plan-react" tabindex="-1">第三站：复杂任务使用 Plan + ReAct <a class="header-anchor" href="#第三站-复杂任务使用-plan-react" aria-label="Permalink to &quot;第三站：复杂任务使用 Plan + ReAct&quot;">​</a></h2><p>在面试中我建议你使用 Plan + ReAct 的混合形态，比较复杂，在面试中好展开。你要记住，没有简单的 Agent，如果你的 Agent 很简单，那就说明你没有深入思考。</p><p>这部分你要说 Plan 决定总体目标、任务步骤和依赖关系；执行到具体步骤之后，再让对应Agent 根据当前 Observation 动态选择 Action。然后顺手带出专栏中的 G4C：</p><ul><li>Goal、Context、Choice、Checkpoint、Correction。</li></ul><p>但是不要重新解释五个词。只需要告诉面试官的 Plan 不是一个简单步骤列表，而是一个能够检查和纠偏的运行时对象。这句话已经够用了，剩下的如果面试官追问你再回答。</p><h2 id="第四站-有-plan-就一定要提-replan" tabindex="-1">第四站：有 Plan，就一定要提 Replan <a class="header-anchor" href="#第四站-有-plan-就一定要提-replan" aria-label="Permalink to &quot;第四站：有 Plan，就一定要提 Replan&quot;">​</a></h2><p>这是非常值得主动补的一句话。你要告诉面试官 Plan 执行过程中如果上下文发生变化、关键假设不成立、工具不可用或者 Checkpoint 没通过，会进入 Correction。但 Correction 不等于马上重新生成整个 Plan。</p><p>你要优先 Retry ，而后考虑当前步骤调整，再考虑局部 Replan ，实在不行则考虑回滚Checkpoint，逼不得已全局 Replan。这样能够体现你对长任务的理解。</p><p>如果还想展现亮点，可以补一句对严重依赖外部工具的关键步骤，你会考虑先做最小化 Try，确认关键依赖成立之后再正式扩大执行。不要主动把 TCC 全讲完，等面试官追问。</p><h2 id="第五站-一定要提上下文管理" tabindex="-1">第五站：一定要提上下文管理 <a class="header-anchor" href="#第五站-一定要提上下文管理" aria-label="Permalink to &quot;第五站：一定要提上下文管理&quot;">​</a></h2><p>如果你的 Agent 已经讲到了 Plan、ReAct 和多轮执行，还完全不谈 Context，那就会显得非常奇怪。这里不需要重新介绍整套上下文理论，你只需要结合业务举例。例如短期 Context 可能有最近对话、当前 Goal、Plan、Step、约束、工具结果。长期 Context 可能有历史对话、历史任务、用户画像、长期事实。</p><p>而后补充说明上下文不能无限塞，所以会做筛选、压缩和摘要；原始细节仍然保留，需要的时候再召回。这样就把上下文管理、摘要和细节召回全部带到了。</p><h3 id="c-端-agent-尽量主动提用户画像" tabindex="-1">C 端 Agent，尽量主动提用户画像 <a class="header-anchor" href="#c-端-agent-尽量主动提用户画像" aria-label="Permalink to &quot;C 端 Agent，尽量主动提用户画像&quot;">​</a></h3><p>如果是电商、教育、社交、内容推荐之类的 C 端 Agent，我建议你尽量主动提用户画像。但是不能直说我记录用户喜欢什么，你要高级一点，比如说谈到用户画像，会区分短期偏好和长期稳定偏好，不会因为用户偶尔说了一句话就永久修改画像。</p><p>这句话非常适合引导面试官继续追问怎么区分临时性偏好和永久性偏好修改。接下来你就可以进入准备好的用户画像内容。</p><h2 id="第六站-检索要同时讲-有什么数据-和-怎么查" tabindex="-1">第六站：检索要同时讲“有什么数据”和“怎么查” <a class="header-anchor" href="#第六站-检索要同时讲-有什么数据-和-怎么查" aria-label="Permalink to &quot;第六站：检索要同时讲“有什么数据”和“怎么查”&quot;">​</a></h2><p>讲 RAG 的时候，不要直接开始背 Embedding 、向量库、Top-K 和 Rerank。你要先结合 XXAgent 说明它能查询哪些东西。例如业务知识库、历史对话、用户画像、业务数据库、实时状态、外部搜索、历史任务结果。然后说明你的核心思想：不是把用户原话直接拿去搜，而是根据当前 Goal 和 Plan 判断还缺什么信息，再决定查什么、去哪里查。</p><p>最后简单补充入库侧会处理 Chunk、层次文档、元数据和权限；检索侧使用向量、关键词、结构化查询、多路召回和 Rerank。差不多就够了，真正的 RAG 细节等面试官追问。</p><h2 id="最后一句带过可观测性" tabindex="-1">最后一句带过可观测性 <a class="header-anchor" href="#最后一句带过可观测性" aria-label="Permalink to &quot;最后一句带过可观测性&quot;">​</a></h2><p>可观测性一般不是这道题的核心，所以一两句话结束。你可以说整条链路会有 Trace，把Intent、Plan、Action、Observation、Context 变化、检索证据和 Replan 串起来，同时采集任务成功率、工具成功率、Replan 率、用户纠正率等指标。</p><p>这样面试官至少知道你的 Agent 不是一个黑盒。</p><h2 id="最终通用话术模板" tabindex="-1">最终通用话术模板 <a class="header-anchor" href="#最终通用话术模板" aria-label="Permalink to &quot;最终通用话术模板&quot;">​</a></h2><p>下面这一段才是这一讲最重要的东西。你可以把 XX Agent 替换成电商 Agent、营销 Agent、客服 Agent、保险 Agent、教育 Agent 等任何业务。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AIAgent%E7%B3%BB%E7%BB%9F%E8%AE%BE%E8%AE%A1%E9%9D%A2%E8%AF%95%E7%8E%B0%E5%9C%BA/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AIAgent%E7%B3%BB%E7%BB%9F%E8%AE%BE%E8%AE%A1%E9%9D%A2%E8%AF%95%E7%8E%B0%E5%9C%BA/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" alt=""></a></p><p>如果面试官听完还觉得不太理解，你就可以参考我在 ReAct 部分总结的内容，你讲一个故事，将这些都串起来，就基本没有破绽了。</p><h2 id="最后-不要只准备答案-要准备证据" tabindex="-1">最后：不要只准备答案，要准备证据 <a class="header-anchor" href="#最后-不要只准备答案-要准备证据" aria-label="Permalink to &quot;最后：不要只准备答案，要准备证据&quot;">​</a></h2><p>这套模板只是骨架，不能代替项目经验。面试前，你至少要准备一个完整案例，并能回答下面这些问题：</p><ol><li><p>用户要完成什么任务？</p></li><li><p>最初采用了什么方案？</p></li><li><p>这个方案在哪里失败了？</p></li><li><p>你用什么数据证明它失败了？</p></li><li><p>为什么选择现在的架构？</p></li><li><p>你放弃过哪些替代方案？</p></li><li><p>当前方案增加了什么成本和风险？</p></li><li><p>工具失败或用户改需求时，系统如何恢复？</p></li><li><p>你怎样评测它是否真的变好了？</p></li><li><p>如果重新做一次，你会改变什么？</p></li></ol><p>面试结束后，也要及时记录面试官追问了什么、自己在哪些地方回答得含糊、哪些判断缺少数据支持。</p><p>多参加几次面试，确实能帮助你了解市场要求。但更重要的不是摸清面试官“喜欢听什么”，而是逐渐发现自己哪里还欠缺。这才是从会背 Agent 概念，到真正具备 Agent 系统设计能力的分界线。</p><p>好了，这个专栏结束了，希望可以帮助你拿到自己想要的 Offer，最后我准备了一份结课问卷，你可以花两分钟时间填写一下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AIAgent%E7%B3%BB%E7%BB%9F%E8%AE%BE%E8%AE%A1%E9%9D%A2%E8%AF%95%E7%8E%B0%E5%9C%BA/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AIAgent%E7%B3%BB%E7%BB%9F%E8%AE%BE%E8%AE%A1%E9%9D%A2%E8%AF%95%E7%8E%B0%E5%9C%BA/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/2.png" alt=""></a></p>',50)])])}const E=t(i,[["render",p]]);export{c as __pageData,E as default};
